// @ts-check
//
// ESLint is the one linter in this repo; formatting belongs to Prettier.
// Why ESLint and not Biome: docs/decisions/0003-eslint-typed-rules-and-prettier.md
//
//   1. Type-aware typescript-eslint. Code we write gets `strict` + `stylistic`;
//      files generated by create-deepspace@0.44.2 (SCAFFOLD_FILES) get
//      `recommended`, so we do not rewrite SDK-generated code for style.
//      When a scaffold file is rewritten as ours, delete it from the list.
//   2. React hooks (including the React Compiler rules) and jsx-a11y for TSX.
//   3. DeepSpace "product polish" rules that a linter can check
//      (https://docs.deep.space/design/product-polish.md): no browser dialogs,
//      no raw <select>, no hardcoded colours, no pictograph emoji. The rest of
//      that gate is `npm run design:gate`.
//   4. Package-level layer bans. Directory-level layer rules and cycles are
//      dependency-cruiser's job (.dependency-cruiser.cjs), because it resolves
//      real paths instead of matching import strings.
//
// vite-plugin-checker runs this config during `deepspace dev start` (overlay)
// and fails `vite build`, so a lint error also blocks `deepspace deploy`.

import js from '@eslint/js'
import { defineConfig } from 'eslint/config'
import prettier from 'eslint-config-prettier'
import jsxA11y from 'eslint-plugin-jsx-a11y'
import reactHooks from 'eslint-plugin-react-hooks'
import tseslint from 'typescript-eslint'

/**
 * Files generated by create-deepspace@0.44.2 that we have not rewritten.
 * `?app?` matches the `(app)` route group; brackets are escaped for minimatch.
 */
const SCAFFOLD_FILES = [
  'worker.ts',
  'prerender.ts',
  'prerender.test.ts',
  'src/main.tsx',
  'src/constants.ts',
  'src/nav.ts',
  'src/seo.ts',
  'src/themes.ts',
  'src/products.ts',
  'src/subscriptions.ts',
  'src/integrations.ts',
  'src/stale-chunk-recovery.ts',
  'src/prerender-entry.tsx',
  'src/prerender-entry.test.tsx',
  'src/lib/utils.ts',
  'src/ai/**',
  'src/server/action-routes.ts',
  'src/server/http-routes.ts',
  'src/server/realtime-routes.ts',
  'src/components/ui/**',
  'src/components/ErrorScreen.tsx',
  'src/components/Seo.tsx',
  'src/pages/_app.tsx',
  'src/pages/index.tsx',
  'src/pages/?app?/_layout.tsx',
  'src/pages/?app?/?protected?/_layout.tsx',
  'src/pages/?app?/?protected?/api-status.tsx',
  'src/pages/?app?/?protected?/settings.tsx',
  'src/schemas/users-schema.ts',
  'src/schemas/admin-schema.ts',
  'tests/api.spec.ts',
  'tests/smoke.spec.ts',
  'tests/helpers/errors.ts',
  'tests/playwright.config.ts',
]

/** Rule settings shared by strict and scaffold TypeScript. */
const typescriptRules = {
  '@typescript-eslint/consistent-type-imports': ['error', { fixStyle: 'inline-type-imports' }],
  '@typescript-eslint/switch-exhaustiveness-check': [
    'error',
    { considerDefaultExhaustiveForUnions: true },
  ],
  '@typescript-eslint/restrict-template-expressions': [
    'error',
    { allowNumber: true, allowBoolean: true },
  ],
  '@typescript-eslint/no-unused-vars': [
    'error',
    { argsIgnorePattern: '^_', varsIgnorePattern: '^_', caughtErrorsIgnorePattern: '^_' },
  ],
}

/** Hardcoded colours in class strings. `shadow-[...rgba()]` stays allowed: the docs prescribe it. */
const HARDCODED_COLOR =
  '/#[0-9a-fA-F]{3}\\b|#[0-9a-fA-F]{6}\\b|(?<!shadow-\\[[^\\s\\]]*)rgba?\\(\\s*[0-9]|\\b(violet|indigo|purple|fuchsia|rose|amber|emerald|teal|cyan|sky|blue|green|red|orange|yellow|lime|pink|slate|gray|zinc|neutral|stone)-[0-9]{2,3}\\b/'

/** Pictograph emoji (U+1F000-U+1FFFF). Plain marks such as ✓ → ★ stay allowed. */
const PICTOGRAPH = '/[\\u{1F000}-\\u{1FFFF}]/u'

const COLOR_MESSAGE =
  'No hardcoded colours: use semantic tokens (bg-primary, text-muted-foreground, ...).'

export default defineConfig(
  {
    ignores: [
      'dist/**',
      'coverage/**',
      'node_modules/**',
      '.wrangler/**',
      '.vite/**',
      '.deepspace/**',
      '.agents/**',
      '.claude/**',
      'test-results/**',
      'playwright-report/**',
      // Generated by generouted; carries a blanket eslint-disable.
      'src/router.ts',
      // macOS AppleDouble metadata files (binary).
      '**/._*',
    ],
  },

  js.configs.recommended,

  // 1a. Every TypeScript file: type-aware `recommended`.
  {
    files: ['**/*.{ts,tsx}'],
    extends: [tseslint.configs.recommendedTypeChecked],
    languageOptions: {
      parserOptions: { projectService: true, tsconfigRootDir: import.meta.dirname },
    },
    rules: typescriptRules,
  },

  // 1b. Code we write: `strict` + `stylistic` on top.
  {
    files: ['**/*.{ts,tsx}'],
    ignores: SCAFFOLD_FILES,
    extends: [tseslint.configs.strictTypeChecked, tseslint.configs.stylisticTypeChecked],
    rules: {
      ...typescriptRules,
      '@typescript-eslint/consistent-type-exports': 'error',
      // Action results and records are discriminated unions; narrowing on them
      // must stay readable.
      '@typescript-eslint/no-unnecessary-condition': [
        'error',
        { allowConstantLoopConditions: true },
      ],
    },
  },

  // 1c. Known findings in the generated code (15 at 0.44.2). Re-check them
  //     after each `deepspace app update` instead of patching SDK code by hand.
  {
    files: SCAFFOLD_FILES,
    rules: {
      '@typescript-eslint/no-unnecessary-type-assertion': 'off',
      '@typescript-eslint/consistent-type-imports': 'off',
      '@typescript-eslint/require-await': 'off',
      '@typescript-eslint/no-unsafe-assignment': 'off',
      '@typescript-eslint/no-misused-promises': 'off',
    },
  },

  // Plain JS config files belong to no tsconfig project.
  {
    files: ['**/*.{js,cjs,mjs}'],
    extends: [tseslint.configs.disableTypeChecked],
  },

  // 2 + 3. React: hooks, accessibility and the product-polish rules.
  {
    files: ['src/**/*.tsx'],
    extends: [reactHooks.configs.flat['recommended-latest'], jsxA11y.flatConfigs.recommended],
    rules: {
      'no-alert': 'error',
      'no-restricted-syntax': [
        'error',
        {
          selector: "JSXOpeningElement[name.name='select']",
          message: 'Use Select from @/components/ui, not a native <select>.',
        },
        {
          selector: `JSXAttribute[name.name='className'] Literal[value=${HARDCODED_COLOR}]`,
          message: COLOR_MESSAGE,
        },
        {
          selector: `JSXAttribute[name.name='className'] TemplateElement[value.raw=${HARDCODED_COLOR}]`,
          message: COLOR_MESSAGE,
        },
        {
          selector: `JSXText[value=${PICTOGRAPH}]`,
          message: 'No pictograph emoji in UI chrome: use lucide-react icons or text.',
        },
      ],
    },
  },
  {
    // The kit's primitives forward htmlFor and friends through props.
    files: ['src/components/ui/**'],
    rules: { 'jsx-a11y/label-has-associated-control': 'off' },
  },

  // 4a. Pure domain code: deterministic, no runtime packages.
  {
    files: ['src/domain/**'],
    rules: {
      'no-restricted-imports': [
        'error',
        {
          patterns: [
            {
              group: [
                'deepspace',
                'deepspace/*',
                'react',
                'react-dom',
                'react-*',
                'hono',
                'hono/*',
                'zod',
                '@/*',
              ],
              message:
                'src/domain is plain TypeScript with no runtime packages (docs/architecture.md).',
            },
          ],
        },
      ],
      // Time and randomness are inputs, so domain code stays testable and replayable.
      'no-restricted-properties': [
        'error',
        { object: 'Date', property: 'now', message: 'Take `now` as an argument.' },
        {
          object: 'Math',
          property: 'random',
          message: 'Take randomness as an argument or derive it from a seed.',
        },
      ],
      'no-restricted-globals': [
        'error',
        { name: 'Date', message: 'Take time as epoch milliseconds.' },
      ],
    },
  },

  // 4b. Contracts are shared by the browser and the Worker.
  {
    files: ['src/contracts/**'],
    rules: {
      'no-restricted-imports': [
        'error',
        {
          paths: [
            {
              name: 'deepspace',
              message: 'Contracts may import types from deepspace/schema only.',
            },
            {
              name: 'deepspace/worker',
              message: 'Contracts may import types from deepspace/schema only.',
            },
          ],
          patterns: [
            {
              group: ['react', 'react-*', 'hono', 'hono/*'],
              message: 'Contracts are runtime-neutral.',
            },
          ],
        },
      ],
    },
  },

  // 4c. Worker code: no browser SDK, no React.
  {
    files: [
      'worker.ts',
      'src/actions/**',
      'src/ai/**',
      'src/server/**',
      'src/cron.ts',
      'src/jobs.ts',
    ],
    rules: {
      'no-restricted-imports': [
        'error',
        {
          paths: [
            {
              name: 'deepspace',
              message: 'Worker code imports deepspace/worker, not the browser SDK.',
            },
          ],
          patterns: [
            {
              group: ['react', 'react-dom', 'react-*'],
              message: 'Worker code must not import React.',
            },
          ],
        },
      ],
    },
  },

  // 4d. Browser code: no Worker SDK.
  {
    files: [
      'src/pages/**',
      'src/components/**',
      'src/features/**',
      'src/client/**',
      'src/main.tsx',
    ],
    rules: {
      'no-restricted-imports': [
        'error',
        {
          paths: [
            { name: 'deepspace/worker', message: 'Browser code must not import deepspace/worker.' },
          ],
        },
      ],
    },
  },

  // Tests may assert non-null on fixtures they just built.
  {
    files: ['**/*.test.{ts,tsx}', 'tests/**'],
    rules: { '@typescript-eslint/no-non-null-assertion': 'off' },
  },

  // Keep last: turns off every rule that would fight Prettier.
  prettier,
)
